mapper.select:
SELECT TPC.FACTORY_CODE AS factoryCode, TPC.PRODUCT_CODE AS productCode, TPC.SPEC_CODE AS specCode, TPC.CONSTRUCTION_CODE AS constructionCode, TPC.EMBRYO_CODE AS embryoCode, TPC.PRODUCTION_VERSION AS productionVersion, TPC.MOULD_METHOD AS mouldMethod, TPC.BOM_VERSION AS bomVersion, TPC.CURING_TIME AS curingTime, TPC.CURING_TIME2 AS curingTime2, TPC.HYDRAULIC_PRESSURE_CURING_TIME AS hydraulicPressureCuringTime, TPC.HYDRAULIC_PRESSURE_CURING_TIME2 AS hydraulicPressureCuringTime2, TPC.MOLD_CAVITY AS moldCavity, TPC.MOULD_CLAMPING_PRESSURE AS mouldClampingPressure FROM T_MDM_PRODUCT_CONSTRUCTION TPC WHERE 1=1
AND TPC.FACTORY_CODE = #{factoryCode}
AND TPC.SPEC_CODE IN
#{specStr}

select pc.EMBRYO_CODE as embryoCode, pc.PRODUCT_CODE as productCode, pi.PRODUCT_DESC as productDesc, pc.SPEC_CODE as specCode from t_mdm_product_construction pc left join t_mdm_product_info pi on pc.PRODUCT_CODE = pi.PRODUCT_CODE WHERE pc.IS_DELETE = '0'
AND pc.FACTORY_CODE = #{factoryCode}
AND pc.SPEC_CODE IN
#{specStr}

SELECT TPC.ID AS id, TPC.FACTORY_CODE AS factoryCode, TPC.PRODUCT_CODE AS productCode, TPC.SPEC_CODE AS specCode, TPC.CONSTRUCTION_CODE AS constructionCode, TPC.EMBRYO_CODE AS embryoCode, '' AS productionVersion, TPC.MOULD_METHOD AS mouldMethod, 1 AS bomVersion, TEMP.CURING_TIME AS curingTime, TEMP.CURING_TIME2 AS curingTime2, TEMP.HYDRAULIC_PRESSURE_CURING_TIME AS hydraulicPressureCuringTime, TEMP.HYDRAULIC_PRESSURE_CURING_TIME2 AS hydraulicPressureCuringTime2, TEMP.MOLD_CAVITY AS moldCavity, TEMP.MOULD_CLAMPING_PRESSURE AS mouldClampingPressure FROM T_MDM_PRODUCT_CONSTRUCTION TPC INNER JOIN (
SELECT #{item.factoryCode} AS FACTORY_CODE, #{item.specCode} AS SPEC_CODE, #{item.embryoCode} AS EMBRYO_CODE, #{item.curingTime} AS CURING_TIME, #{item.curingTime2} AS CURING_TIME2, #{item.hydraulicPressureCuringTime} AS HYDRAULIC_PRESSURE_CURING_TIME, #{item.hydraulicPressureCuringTime2} AS HYDRAULIC_PRESSURE_CURING_TIME2, #{item.moldCavity} AS MOLD_CAVITY, #{item.mouldClampingPressure} AS MOULD_CLAMPING_PRESSURE, '' AS PRODUCTION_VERSION
) TEMP ON TPC.FACTORY_CODE = TEMP.FACTORY_CODE AND TPC.SPEC_CODE = TEMP.SPEC_CODE AND TPC.EMBRYO_CODE = TEMP.EMBRYO_CODE WHERE TPC.IS_DELETE = 0

SELECT TPC.* FROM TPC INNER JOIN (
SELECT #{item.factoryCode} AS FACTORY_CODE, #{item.productCode} AS PRODUCT_CODE, #{item.mouldMethod} AS MOULD_METHOD
) TEMP ON TPC.FACTORY_CODE = TEMP.FACTORY_CODE AND TPC.PRODUCT_CODE = TEMP.PRODUCT_CODE AND TPC.MOULD_METHOD = TEMP.MOULD_METHOD WHERE TPC.IS_DELETE = 0

SELECT TPC.* FROM TPC INNER JOIN (
SELECT #{item.factoryCode} AS FACTORY_CODE, #{item.embryoCode} AS EMBRYO_CODE
) TEMP ON TPC.FACTORY_CODE = TEMP.FACTORY_CODE AND TPC.EMBRYO_CODE = TEMP.EMBRYO_CODE WHERE TPC.IS_DELETE = 0 AND TPC.PRODUCT_CODE NOT LIKE 'T%' AND TPC.CURING_TIME IS NOT NULL

SELECT TPC.* FROM TPC INNER JOIN (
SELECT #{item.factoryCode} AS FACTORY_CODE, #{item.specCode} AS SPEC_CODE
) TEMP ON TPC.FACTORY_CODE = TEMP.FACTORY_CODE AND TPC.SPEC_CODE = TEMP.SPEC_CODE WHERE TPC.IS_DELETE = 0
